describe('Image Gallery Lightbox Modal', () => {
  beforeEach(() => {
    cy.visit('/gallery');
  });

  it('should open lightbox modal when clicking an image in gallery', () => {
    // Verify gallery is visible
    cy.get('[data-testid="image-gallery"]').should('be.visible');

    // Verify images are present
    cy.get('[data-testid="gallery-image"]').should('have.length.greaterThan', 0);

    // Click the first image to open lightbox
    cy.get('[data-testid="gallery-image"]').first().click();

    // Verify lightbox modal is visible
    cy.get('[data-testid="lightbox-modal"]').should('be.visible');

    // Verify modal contains the clicked image
    cy.get('[data-testid="lightbox-image"]').should('be.visible');
    cy.get('[data-testid="lightbox-image"]').should('have.attr', 'src');

    // Verify close button is visible
    cy.get('[data-testid="lightbox-close-button"]').should('be.visible');

    // Verify modal has overlay
    cy.get('[data-testid="lightbox-overlay"]').should('be.visible');
  });

  it('should close lightbox modal when clicking close button or pressing escape', () => {
    // Open lightbox by clicking an image
    cy.get('[data-testid="gallery-image"]').first().click();
    cy.get('[data-testid="lightbox-modal"]').should('be.visible');

    // Close lightbox by clicking the close button
    cy.get('[data-testid="lightbox-close-button"]').click();

    // Verify lightbox is closed
    cy.get('[data-testid="lightbox-modal"]').should('not.exist');

    // Open lightbox again
    cy.get('[data-testid="gallery-image"]').first().click();
    cy.get('[data-testid="lightbox-modal"]').should('be.visible');

    // Close lightbox by pressing escape key
    cy.get('body').type('{esc}');

    // Verify lightbox is closed
    cy.get('[data-testid="lightbox-modal"]').should('not.exist');
  });
});
